def specialFilter(nums):
    def is_odd(n):
        return n % 2 != 0

    def first_digit(n):
        n = abs(n)
        while n >= 10:
            n //= 10
        return n

    def last_digit(n):
        return abs(n) % 10

    count = 0
    for num in nums:
        if num > 10 and is_odd(first_digit(num)) and is_odd(last_digit(num)):
            count += 1
    return count
